import { test, expect } from '@playwright/test';

test.describe('Column Visibility Toggle', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should display settings menu button', async ({ page }) => {
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();
  });

  test('should open settings menu when settings button is clicked', async ({ page }) => {
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    const settingsMenu = page.getByRole('menu', { name: /settings/i });
    await expect(settingsMenu).toBeVisible();
  });

  test('should toggle column visibility from settings menu', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Find and click column visibility option
    const columnVisibilityOption = page.getByRole('menuitem', { name: /column visibility/i });
    await expect(columnVisibilityOption).toBeVisible();
    await columnVisibilityOption.click();

    // Verify column visibility dialog appears
    const visibilityDialog = page.getByRole('dialog', { name: /column visibility/i });
    await expect(visibilityDialog).toBeVisible();
  });

  test('should hide column when unchecking column checkbox', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Open column visibility dialog
    const columnVisibilityOption = page.getByRole('menuitem', { name: /column visibility/i });
    await columnVisibilityOption.click();

    // Get initial column header
    const columnHeader = page.getByRole('columnheader', { name: /name/i });
    await expect(columnHeader).toBeVisible();

    // Uncheck the Name column checkbox
    const nameCheckbox = page.getByRole('checkbox', { name: /name/i });
    await nameCheckbox.uncheck();

    // Verify column is hidden
    await expect(columnHeader).not.toBeVisible();
  });

  test('should show column when checking column checkbox', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Open column visibility dialog
    const columnVisibilityOption = page.getByRole('menuitem', { name: /column visibility/i });
    await columnVisibilityOption.click();

    // Uncheck a column first
    const emailCheckbox = page.getByRole('checkbox', { name: /email/i });
    await emailCheckbox.uncheck();

    // Verify column is hidden
    const emailHeader = page.getByRole('columnheader', { name: /email/i });
    await expect(emailHeader).not.toBeVisible();

    // Check the Email column checkbox
    await emailCheckbox.check();

    // Verify column is visible again
    await expect(emailHeader).toBeVisible();
  });

  test('should persist column visibility changes after closing menu', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Open column visibility dialog
    const columnVisibilityOption = page.getByRole('menuitem', { name: /column visibility/i });
    await columnVisibilityOption.click();

    // Hide a column
    const phoneCheckbox = page.getByRole('checkbox', { name: /phone/i });
    await phoneCheckbox.uncheck();

    // Close the dialog
    const closeButton = page.getByRole('button', { name: /close|done|apply/i }).first();
    await closeButton.click();

    // Verify column remains hidden
    const phoneHeader = page.getByRole('columnheader', { name: /phone/i });
    await expect(phoneHeader).not.toBeVisible();
  });

  test('should display all column options in visibility menu', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Open column visibility dialog
    const columnVisibilityOption = page.getByRole('menuitem', { name: /column visibility/i });
    await columnVisibilityOption.click();

    // Verify multiple column checkboxes are present
    const nameCheckbox = page.getByRole('checkbox', { name: /name/i });
    const emailCheckbox = page.getByRole('checkbox', { name: /email/i });
    const phoneCheckbox = page.getByRole('checkbox', { name: /phone/i });

    await expect(nameCheckbox).toBeVisible();
    await expect(emailCheckbox).toBeVisible();
    await expect(phoneCheckbox).toBeVisible();
  });

  test('should toggle multiple columns visibility independently', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Open column visibility dialog
    const columnVisibilityOption = page.getByRole('menuitem', { name: /column visibility/i });
    await columnVisibilityOption.click();

    // Hide Name column
    const nameCheckbox = page.getByRole('checkbox', { name: /name/i });
    await nameCheckbox.uncheck();

    // Hide Email column
    const emailCheckbox = page.getByRole('checkbox', { name: /email/i });
    await emailCheckbox.uncheck();

    // Keep Phone column visible
    const phoneCheckbox = page.getByRole('checkbox', { name: /phone/i });
    await expect(phoneCheckbox).toBeChecked();

    // Close dialog
    const closeButton = page.getByRole('button', { name: /close|done|apply/i }).first();
    await closeButton.click();

    // Verify Name and Email are hidden
    const nameHeader = page.getByRole('columnheader', { name: /name/i });
    const emailHeader = page.getByRole('columnheader', { name: /email/i });
    const phoneHeader = page.getByRole('columnheader', { name: /phone/i });

    await expect(nameHeader).not.toBeVisible();
    await expect(emailHeader).not.toBeVisible();
    await expect(phoneHeader).toBeVisible();
  });
});
